using Microsoft.Data.Sqlite; using Workbench.Storage.Database;
namespace Workbench.Storage.Workers;
public sealed record StoredTaskEvent(Guid EventId,Guid ProjectId,Guid TaskId,Guid? ExecutionId,string Type,string Payload,DateTimeOffset CreatedAt);
public sealed class TaskEventRepository(WorkbenchDatabase database){private readonly WorkbenchDatabase _d=database; public async Task AppendAsync(StoredTaskEvent e,CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT OR IGNORE INTO task_events(id,project_id,task_id,execution_id,event_type,payload_json,created_at) VALUES($i,$p,$t,$x,$y,$z,$a)";q.Parameters.AddWithValue("$i",e.EventId.ToString());q.Parameters.AddWithValue("$p",e.ProjectId.ToString());q.Parameters.AddWithValue("$t",e.TaskId.ToString());q.Parameters.AddWithValue("$x",(object?)e.ExecutionId?.ToString()??DBNull.Value);q.Parameters.AddWithValue("$y",e.Type);q.Parameters.AddWithValue("$z",e.Payload);q.Parameters.AddWithValue("$a",e.CreatedAt.ToString("O"));await q.ExecuteNonQueryAsync(ct);}}
